const Database = require('better-sqlite3');
const crypto = require('crypto');
const XLSX = require('xlsx');
const path = require('path');

const DB_PATH = path.join(__dirname, 'brickfall.db');

function initDB() {
  const db = new Database(DB_PATH);
  db.pragma('journal_mode = WAL');

  // Check if already initialized
  const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all();
  const tableNames = tables.map(t => t.name);

  if (!tableNames.includes('users')) {
    initializeSchema(db);
    seedData(db);
  }

  return db;
}

function initializeSchema(db) {
  db.exec(`
    CREATE TABLE users (
      id INTEGER PRIMARY KEY,
      email TEXT UNIQUE NOT NULL,
      name TEXT NOT NULL,
      initials TEXT NOT NULL,
      password_hash TEXT NOT NULL,
      password_salt TEXT NOT NULL,
      highest_level INTEGER DEFAULT 1,
      best_score INTEGER DEFAULT 0,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE tokens (
      id INTEGER PRIMARY KEY,
      user_id INTEGER NOT NULL UNIQUE,
      token TEXT UNIQUE NOT NULL,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );

    CREATE TABLE levels (
      id INTEGER PRIMARY KEY,
      level_number INTEGER UNIQUE NOT NULL,
      name TEXT NOT NULL,
      base_speed INTEGER NOT NULL,
      speed_cap INTEGER NOT NULL,
      accent TEXT NOT NULL
    );

    CREATE TABLE bricks (
      id INTEGER PRIMARY KEY,
      level_number INTEGER NOT NULL,
      row_idx INTEGER NOT NULL,
      col_idx INTEGER NOT NULL,
      type TEXT NOT NULL,
      drop_type TEXT,
      FOREIGN KEY (level_number) REFERENCES levels(level_number),
      UNIQUE(level_number, row_idx, col_idx)
    );

    CREATE TABLE leaderboard (
      id INTEGER PRIMARY KEY,
      user_id INTEGER,
      initials TEXT NOT NULL,
      score INTEGER NOT NULL,
      level INTEGER NOT NULL,
      achieved_at TEXT NOT NULL,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
    );

    CREATE TABLE run_records (
      id INTEGER PRIMARY KEY,
      user_id INTEGER NOT NULL,
      run_id TEXT UNIQUE NOT NULL,
      revision INTEGER NOT NULL,
      outcome TEXT,
      level INTEGER NOT NULL,
      score INTEGER NOT NULL,
      finished_at TEXT,
      snapshot TEXT,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );

    CREATE TABLE active_runs (
      id INTEGER PRIMARY KEY,
      user_id INTEGER NOT NULL UNIQUE,
      run_id TEXT UNIQUE NOT NULL,
      revision INTEGER NOT NULL,
      level INTEGER NOT NULL,
      score INTEGER NOT NULL,
      lives INTEGER NOT NULL,
      combo INTEGER NOT NULL,
      next_extra_life INTEGER NOT NULL,
      power_up TEXT,
      power_seconds REAL,
      paddle_width INTEGER NOT NULL,
      balls TEXT NOT NULL,
      drops TEXT NOT NULL,
      bricks TEXT NOT NULL,
      accumulated_time REAL NOT NULL,
      unlocked_levels TEXT NOT NULL,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );

    CREATE TABLE constants (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL
    );

    CREATE TABLE operation_receipts (
      id INTEGER PRIMARY KEY,
      user_id INTEGER NOT NULL,
      operation_id TEXT NOT NULL,
      request_hash TEXT NOT NULL,
      status_code INTEGER NOT NULL,
      response TEXT NOT NULL,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      UNIQUE(user_id, operation_id),
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );

    CREATE TABLE checkpoints (
      id INTEGER PRIMARY KEY,
      user_id INTEGER NOT NULL UNIQUE,
      run_id TEXT UNIQUE NOT NULL,
      revision INTEGER NOT NULL,
      level INTEGER NOT NULL,
      score INTEGER NOT NULL,
      lives INTEGER NOT NULL,
      combo INTEGER NOT NULL,
      next_extra_life INTEGER NOT NULL,
      power_up TEXT,
      power_seconds REAL,
      paddle_width INTEGER NOT NULL,
      balls TEXT NOT NULL,
      drops TEXT NOT NULL,
      bricks TEXT NOT NULL,
      accumulated_time REAL NOT NULL,
      next_outcome TEXT,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );
  `);
}

function seedData(db) {
  const wb = XLSX.readFile('/assets/artifacts/brickfall_seed.xlsx');

  // Seed users
  const usersWs = wb.Sheets['Users'];
  const users = XLSX.utils.sheet_to_json(usersWs);

  for (const user of users) {
    const salt = crypto.randomBytes(16).toString('hex');
    const hash = crypto.pbkdf2Sync(user.password, salt, 100000, 64, 'sha256').toString('hex');

    db.prepare(`
      INSERT INTO users (email, name, initials, password_hash, password_salt, highest_level, best_score)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `).run(user.email, user.name, user.initials, hash, salt, user.highest_level, user.best_score);
  }

  // Seed levels
  const levelsWs = wb.Sheets['Levels'];
  const levels = XLSX.utils.sheet_to_json(levelsWs);

  for (const level of levels) {
    db.prepare(`
      INSERT INTO levels (level_number, name, base_speed, speed_cap, accent)
      VALUES (?, ?, ?, ?, ?)
    `).run(level.level, level.name, level.base_speed, level.speed_cap, level.accent);
  }

  // Seed bricks
  const bricksWs = wb.Sheets['Bricks'];
  const bricks = XLSX.utils.sheet_to_json(bricksWs);

  for (const brick of bricks) {
    const dropType = brick.drop && brick.drop.trim() ? brick.drop : null;
    db.prepare(`
      INSERT INTO bricks (level_number, row_idx, col_idx, type, drop_type)
      VALUES (?, ?, ?, ?, ?)
    `).run(brick.level, brick.row, brick.column, brick.type, dropType);
  }

  // Seed leaderboard
  const leaderboardWs = wb.Sheets['Leaderboard'];
  const leaderboard = XLSX.utils.sheet_to_json(leaderboardWs);

  for (const entry of leaderboard) {
    let userId = null;
    if (entry.email && entry.email.trim()) {
      const user = db.prepare('SELECT id FROM users WHERE email = ?').get(entry.email);
      if (user) userId = user.id;
    }

    db.prepare(`
      INSERT INTO leaderboard (user_id, initials, score, level, achieved_at)
      VALUES (?, ?, ?, ?, ?)
    `).run(userId, entry.initials, entry.score, entry.level, entry.achieved_at);
  }

  // Seed constants
  const constantsWs = wb.Sheets['Constants'];
  const constants = XLSX.utils.sheet_to_json(constantsWs);

  for (const constant of constants) {
    db.prepare(`
      INSERT INTO constants (key, value)
      VALUES (?, ?)
    `).run(constant.key, constant.value);
  }

  // Import scenarios
  const scenarios = require('/assets/artifacts/brickfall_scenarios.json');

  // Add guest leaderboard entries
  for (const entry of scenarios.guest_leaderboard) {
    db.prepare(`
      INSERT INTO leaderboard (user_id, initials, score, level, achieved_at)
      VALUES (?, ?, ?, ?, ?)
    `).run(null, entry.initials, entry.score, entry.level, entry.achieved_at);
  }

  // Add personal run fixtures
  for (const fixture of scenarios.personal_run_fixtures) {
    const user = db.prepare('SELECT id FROM users WHERE email = ?').get(fixture.user + '@brickfall.test');
    if (!user) continue;

    db.prepare(`
      INSERT INTO run_records (user_id, run_id, revision, outcome, level, score, finished_at, snapshot)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `).run(user.id, fixture.run_id, 1, fixture.outcome, fixture.level, fixture.score, fixture.finished_at, null);
  }

  // Store checkpoints for Mira and Dev
  const miraUser = db.prepare('SELECT id FROM users WHERE email = ?').get('mira@brickfall.test');
  const devUser = db.prepare('SELECT id FROM users WHERE email = ?').get('dev@brickfall.test');

  if (miraUser && scenarios.checkpoints.mira) {
    const cp = scenarios.checkpoints.mira;
    const runId = `mira-checkpoint-${cp.revision}`;

    db.prepare(`
      INSERT INTO checkpoints (user_id, run_id, revision, level, score, lives, combo, next_extra_life, 
        power_up, power_seconds, paddle_width, balls, drops, bricks, accumulated_time, next_outcome)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      miraUser.id, runId, cp.revision, cp.level, cp.score, cp.lives, cp.combo, cp.next_extra_life,
      cp.power, cp.power_seconds, cp.paddle_width, cp.balls, cp.drop, cp.bricks, 0, cp.next_outcome
    );
  }

  if (devUser && scenarios.checkpoints.dev) {
    const cp = scenarios.checkpoints.dev;
    const runId = `dev-checkpoint-${cp.revision}`;

    db.prepare(`
      INSERT INTO checkpoints (user_id, run_id, revision, level, score, lives, combo, next_extra_life,
        power_up, power_seconds, paddle_width, balls, drops, bricks, accumulated_time, next_outcome)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      devUser.id, runId, cp.revision, cp.level, cp.score, cp.lives, cp.combo, cp.next_extra_life,
      null, null, 118, cp.balls, '', cp.bricks, 0, cp.next_outcome
    );
  }
}

function getDB() {
  return new Database(DB_PATH);
}

function hashPassword(password, salt) {
  return crypto.pbkdf2Sync(password, salt, 100000, 64, 'sha256').toString('hex');
}

function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

function authenticateUser(db, email, password) {
  const user = db.prepare('SELECT * FROM users WHERE email = ?').get(email);
  if (!user) return null;

  const hash = hashPassword(password, user.password_salt);
  if (hash !== user.password_hash) return null;

  // Revoke existing tokens
  db.prepare('DELETE FROM tokens WHERE user_id = ?').run(user.id);

  // Create new token
  const token = generateToken();
  db.prepare('INSERT INTO tokens (user_id, token) VALUES (?, ?)').run(user.id, token);

  return { user, token };
}

function getUserFromToken(db, token) {
  if (!token) return null;
  const record = db.prepare('SELECT u.* FROM users u JOIN tokens t ON u.id = t.user_id WHERE t.token = ?').get(token);
  return record || null;
}

function revokeToken(db, token) {
  db.prepare('DELETE FROM tokens WHERE token = ?').run(token);
}

module.exports = {
  initDB,
  getDB,
  hashPassword,
  generateToken,
  authenticateUser,
  getUserFromToken,
  revokeToken
};

const express = require('express');
const crypto = require('crypto');
const path = require('path');
const { initDB, getDB, authenticateUser, getUserFromToken, revokeToken } = require('./db');

const app = express();
const PORT = 3000;

// Initialize database on startup
const mainDB = initDB();
mainDB.close();

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// Middleware to check authentication
function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const db = getDB();
  const user = getUserFromToken(db, token);
  db.close();

  if (!user) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  req.user = user;
  req.token = token;
  next();
}

// Sign in
app.post('/api/sign-in', (req, res) => {
  const { email, password } = req.body;

  const db = getDB();
  const result = authenticateUser(db, email, password);
  db.close();

  if (!result) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const user = result.user;
  res.json({
    token: result.token,
    user: {
      id: user.id,
      email: user.email,
      name: user.name,
      initials: user.initials
    }
  });
});

// Sign out
app.post('/api/sign-out', authMiddleware, (req, res) => {
  const db = getDB();
  revokeToken(db, req.token);
  db.close();

  res.json({ success: true });
});

// Get game state
app.get('/api/game-state', authMiddleware, (req, res) => {
  const db = getDB();

  const user = db.prepare('SELECT * FROM users WHERE id = ?').get(req.user.id);
  const activeRun = db.prepare('SELECT * FROM active_runs WHERE user_id = ?').get(req.user.id);

  const leaderboard = db.prepare(`
    SELECT initials, score, level, achieved_at 
    FROM leaderboard 
    ORDER BY score DESC, achieved_at ASC
    LIMIT 10
  `).all();

  const unlockedLevels = user.highest_level || 1;

  const runHistory = db.prepare(`
    SELECT run_id, outcome, level, score, finished_at
    FROM run_records
    WHERE user_id = ?
    ORDER BY finished_at DESC
    LIMIT 10
  `).all(req.user.id);

  db.close();

  res.json({
    user: {
      id: user.id,
      email: user.email,
      name: user.name,
      initials: user.initials,
      best_score: user.best_score
    },
    unlockedLevels,
    activeRun: activeRun ? {
      run_id: activeRun.run_id,
      revision: activeRun.revision,
      level: activeRun.level,
      score: activeRun.score,
      lives: activeRun.lives,
      combo: activeRun.combo,
      next_extra_life: activeRun.next_extra_life,
      power_up: activeRun.power_up,
      power_seconds: activeRun.power_seconds,
      paddle_width: activeRun.paddle_width,
      balls: JSON.parse(activeRun.balls),
      drops: JSON.parse(activeRun.drops),
      bricks: JSON.parse(activeRun.bricks),
      accumulated_time: activeRun.accumulated_time,
      unlocked_levels: JSON.parse(activeRun.unlocked_levels)
    } : null,
    leaderboard,
    runHistory
  });
});

// Start new run
app.post('/api/start-run', authMiddleware, (req, res) => {
  const { levelNumber, operationId } = req.body;
  const db = getDB();

  try {
    // Check for duplicate operation
    const existing = db.prepare(`
      SELECT * FROM operation_receipts 
      WHERE user_id = ? AND operation_id = ?
    `).get(req.user.id, operationId);

    if (existing) {
      return res.status(existing.status_code).json(JSON.parse(existing.response));
    }

    const user = db.prepare('SELECT * FROM users WHERE id = ?').get(req.user.id);
    const level = db.prepare('SELECT * FROM levels WHERE level_number = ?').get(levelNumber);

    if (!level) {
      const err = { error: 'Level not found' };
      db.prepare(`
        INSERT INTO operation_receipts (user_id, operation_id, request_hash, status_code, response)
        VALUES (?, ?, ?, ?, ?)
      `).run(req.user.id, operationId, '', 404, JSON.stringify(err));
      db.close();
      return res.status(404).json(err);
    }

    if (levelNumber > user.highest_level) {
      const err = { error: 'Level not unlocked' };
      db.prepare(`
        INSERT INTO operation_receipts (user_id, operation_id, request_hash, status_code, response)
        VALUES (?, ?, ?, ?, ?)
      `).run(req.user.id, operationId, '', 403, JSON.stringify(err));
      db.close();
      return res.status(403).json(err);
    }

    // Load bricks for this level
    const bricks = db.prepare(`
      SELECT row_idx, col_idx, type, drop_type
      FROM bricks
      WHERE level_number = ?
      ORDER BY row_idx, col_idx
    `).all(levelNumber);

    const brickState = {};
    for (const brick of bricks) {
      const key = `${brick.row_idx},${brick.col_idx}`;
      brickState[key] = {
        type: brick.type,
        health: brick.type === 'strong' ? 2 : 1,
        drop: brick.drop_type
      };
    }

    // Create run
    const runId = `run-${req.user.id}-${Date.now()}`;
    const revision = 1;
    const unlockedLevels = Array.from({ length: user.highest_level }, (_, i) => i + 1);

    const initialBalls = [{
      x: 189,
      y: 540,
      vx: 0,
      vy: 0,
      stuck: true,
      primary: true
    }];

    db.prepare(`
      INSERT OR REPLACE INTO active_runs (
        user_id, run_id, revision, level, score, lives, combo, next_extra_life,
        power_up, power_seconds, paddle_width, balls, drops, bricks, accumulated_time, unlocked_levels
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      req.user.id,
      runId,
      revision,
      levelNumber,
      0,
      3,
      1,
      20000,
      null,
      null,
      118,
      JSON.stringify(initialBalls),
      JSON.stringify([]),
      JSON.stringify(brickState),
      0,
      JSON.stringify(unlockedLevels)
    );

    const response = {
      run_id: runId,
      revision,
      level: levelNumber,
      score: 0,
      lives: 3,
      combo: 1,
      next_extra_life: 20000,
      power_up: null,
      power_seconds: null,
      paddle_width: 118,
      balls: initialBalls,
      drops: [],
      bricks: brickState,
      accumulated_time: 0,
      unlocked_levels: unlockedLevels
    };

    db.prepare(`
      INSERT INTO operation_receipts (user_id, operation_id, request_hash, status_code, response)
      VALUES (?, ?, ?, ?, ?)
    `).run(req.user.id, operationId, '', 200, JSON.stringify(response));

    db.close();
    res.json(response);
  } catch (err) {
    console.error('Error starting run:', err);
    db.close();
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Save run state
app.post('/api/save-run', authMiddleware, (req, res) => {
  const { run_id, revision, operationId, state } = req.body;
  const db = getDB();

  try {
    // Check for duplicate operation
    const existing = db.prepare(`
      SELECT * FROM operation_receipts 
      WHERE user_id = ? AND operation_id = ?
    `).get(req.user.id, operationId);

    if (existing) {
      return res.status(existing.status_code).json(JSON.parse(existing.response));
    }

    // Check revision
    const activeRun = db.prepare('SELECT * FROM active_runs WHERE user_id = ? AND run_id = ?')
      .get(req.user.id, run_id);

    if (!activeRun) {
      const err = { error: 'Run not found' };
      db.prepare(`
        INSERT INTO operation_receipts (user_id, operation_id, request_hash, status_code, response)
        VALUES (?, ?, ?, ?, ?)
      `).run(req.user.id, operationId, '', 404, JSON.stringify(err));
      db.close();
      return res.status(404).json(err);
    }

    if (activeRun.revision !== revision) {
      const err = {
        error: 'Stale revision',
        current_revision: activeRun.revision,
        state: {
          level: activeRun.level,
          score: activeRun.score,
          lives: activeRun.lives,
          combo: activeRun.combo,
          next_extra_life: activeRun.next_extra_life,
          power_up: activeRun.power_up,
          power_seconds: activeRun.power_seconds,
          paddle_width: activeRun.paddle_width,
          balls: JSON.parse(activeRun.balls),
          drops: JSON.parse(activeRun.drops),
          bricks: JSON.parse(activeRun.bricks),
          accumulated_time: activeRun.accumulated_time
        }
      };
      db.prepare(`
        INSERT INTO operation_receipts (user_id, operation_id, request_hash, status_code, response)
        VALUES (?, ?, ?, ?, ?)
      `).run(req.user.id, operationId, '', 409, JSON.stringify(err));
      db.close();
      return res.status(409).json(err);
    }

    // Update run state
    const newRevision = revision + 1;
    db.prepare(`
      UPDATE active_runs SET
        revision = ?, level = ?, score = ?, lives = ?, combo = ?, next_extra_life = ?,
        power_up = ?, power_seconds = ?, paddle_width = ?, balls = ?, drops = ?, bricks = ?,
        accumulated_time = ?, updated_at = CURRENT_TIMESTAMP
      WHERE user_id = ? AND run_id = ?
    `).run(
      newRevision,
      state.level,
      state.score,
      state.lives,
      state.combo,
      state.next_extra_life,
      state.power_up || null,
      state.power_seconds || null,
      state.paddle_width,
      JSON.stringify(state.balls),
      JSON.stringify(state.drops),
      JSON.stringify(state.bricks),
      state.accumulated_time,
      req.user.id,
      run_id
    );

    const response = { revision: newRevision, success: true };
    db.prepare(`
      INSERT INTO operation_receipts (user_id, operation_id, request_hash, status_code, response)
      VALUES (?, ?, ?, ?, ?)
    `).run(req.user.id, operationId, '', 200, JSON.stringify(response));

    db.close();
    res.json(response);
  } catch (err) {
    console.error('Error saving run:', err);
    db.close();
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Finish run
app.post('/api/finish-run', authMiddleware, (req, res) => {
  const { run_id, revision, operationId, outcome, level, score } = req.body;
  const db = getDB();

  try {
    // Check for duplicate operation
    const existing = db.prepare(`
      SELECT * FROM operation_receipts 
      WHERE user_id = ? AND operation_id = ?
    `).get(req.user.id, operationId);

    if (existing) {
      return res.status(existing.status_code).json(JSON.parse(existing.response));
    }

    // Check revision
    const activeRun = db.prepare('SELECT * FROM active_runs WHERE user_id = ? AND run_id = ?')
      .get(req.user.id, run_id);

    if (!activeRun) {
      const err = { error: 'Run not found' };
      db.prepare(`
        INSERT INTO operation_receipts (user_id, operation_id, request_hash, status_code, response)
        VALUES (?, ?, ?, ?, ?)
      `).run(req.user.id, operationId, '', 404, JSON.stringify(err));
      db.close();
      return res.status(404).json(err);
    }

    if (activeRun.revision !== revision) {
      const err = {
        error: 'Stale revision',
        current_revision: activeRun.revision
      };
      db.prepare(`
        INSERT INTO operation_receipts (user_id, operation_id, request_hash, status_code, response)
        VALUES (?, ?, ?, ?, ?)
      `).run(req.user.id, operationId, '', 409, JSON.stringify(err));
      db.close();
      return res.status(409).json(err);
    }

    // Record the run
    const finishedAt = new Date().toISOString();
    db.prepare(`
      INSERT INTO run_records (user_id, run_id, revision, outcome, level, score, finished_at)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `).run(req.user.id, run_id, revision, outcome, level, score, finishedAt);

    // Update user's best score and highest level if this is better
    const user = db.prepare('SELECT * FROM users WHERE id = ?').get(req.user.id);
    if (score > user.best_score) {
      db.prepare('UPDATE users SET best_score = ? WHERE id = ?').run(score, req.user.id);
    }
    if (level === 10 && outcome === 'completed' && level > user.highest_level) {
      db.prepare('UPDATE users SET highest_level = ? WHERE id = ?').run(level, req.user.id);
    } else if (level > user.highest_level) {
      db.prepare('UPDATE users SET highest_level = ? WHERE id = ?').run(level, req.user.id);
    }

    // Add to leaderboard if completed or game-over at level 10
    if ((outcome === 'completed' && level === 10) || (outcome === 'game-over' && level >= 1)) {
      db.prepare(`
        INSERT INTO leaderboard (user_id, initials, score, level, achieved_at)
        VALUES (?, ?, ?, ?, ?)
      `).run(req.user.id, user.initials, score, level, finishedAt);
    }

    // Delete the active run
    db.prepare('DELETE FROM active_runs WHERE user_id = ?').run(req.user.id);

    // Get updated leaderboard
    const leaderboard = db.prepare(`
      SELECT initials, score, level, achieved_at
      FROM leaderboard
      ORDER BY score DESC, achieved_at ASC
      LIMIT 10
    `).all();

    const response = {
      success: true,
      outcome,
      level,
      score,
      leaderboard
    };

    db.prepare(`
      INSERT INTO operation_receipts (user_id, operation_id, request_hash, status_code, response)
      VALUES (?, ?, ?, ?, ?)
    `).run(req.user.id, operationId, '', 200, JSON.stringify(response));

    db.close();
    res.json(response);
  } catch (err) {
    console.error('Error finishing run:', err);
    db.close();
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Serve the main HTML file
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Brickfall server running on port ${PORT}`);
});

:root {
  --accent-blue: #56c7ff;
  --accent-green: #7ee787;
  --accent-yellow: #ffd166;
  --dark-bg: #1a1a2e;
  --darker-bg: #0f0f1e;
  --text-primary: #ffffff;
  --text-secondary: #a0a0b0;
  --border-color: #3a3a4e;
  --success-color: #7ee787;
  --warning-color: #ffd166;
  --error-color: #ff6b6b;
  --transition-fast: 150ms;
  --transition-normal: 300ms;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  height: 100%;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background-color: var(--dark-bg);
  color: var(--text-primary);
  line-height: 1.5;
}

body {
  overflow: hidden;
}

.app-container {
  width: 100vw;
  height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--dark-bg) 0%, var(--darker-bg) 100%);
}

.screen {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 10;
}

.screen.active {
  display: flex;
}

/* Sign-in Screen */
.sign-in-form {
  background: var(--darker-bg);
  border: 2px solid var(--border-color);
  border-radius: 8px;
  padding: 3rem 2rem;
  max-width: 350px;
  width: 90%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
}

.sign-in-form h1 {
  font-size: 2.5rem;
  margin-bottom: 2rem;
  text-align: center;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-green));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.form-group {
  margin-bottom: 1.5rem;
}

.form-group label {
  display: block;
  margin-bottom: 0.5rem;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

.form-group input {
  width: 100%;
  padding: 0.75rem;
