class APIClient {
  constructor() {
    this.token = localStorage.getItem('auth_token');
    this.baseURL = '/api';
  }

  setToken(token) {
    this.token = token;
    localStorage.setItem('auth_token', token);
  }

  clearToken() {
    this.token = null;
    localStorage.removeItem('auth_token');
  }

  async request(method, endpoint, body = null) {
    const options = {
      method,
      headers: {
        'Content-Type': 'application/json'
      }
    };

    if (this.token) {
      options.headers['Authorization'] = `Bearer ${this.token}`;
    }

    if (body) {
      options.body = JSON.stringify(body);
    }

    const response = await fetch(`${this.baseURL}${endpoint}`, options);

    if (response.status === 401) {
      this.clearToken();
      window.location.reload();
    }

    const data = await response.json();

    if (!response.ok) {
      const error = new Error(data.error || 'Request failed');
      error.status = response.status;
      error.data = data;
      throw error;
    }

    return data;
  }

  async signIn(email, password) {
    return this.request('POST', '/sign-in', { email, password });
  }

  async signOut() {
    return this.request('POST', '/sign-out');
  }

  async getGameState() {
    return this.request('GET', '/game-state');
  }

  async startRun(levelNumber) {
    const operationId = this.generateOperationId();
    return this.request('POST', '/start-run', {
      levelNumber,
      operationId
    });
  }

  async saveRun(runId, revision, state) {
    const operationId = this.generateOperationId();
    return this.request('POST', '/save-run', {
      run_id: runId,
      revision,
      operationId,
      state
    });
  }

  async finishRun(runId, revision, outcome, level, score) {
    const operationId = this.generateOperationId();
    return this.request('POST', '/finish-run', {
      run_id: runId,
      revision,
      operationId,
      outcome,
      level,
      score
    });
  }

  generateOperationId() {
    return `op-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}

window.api = new APIClient();

class BrickfallGame {
  constructor() {
    this.canvas = document.getElementById('game-canvas');
    this.ctx = this.canvas.getContext('2d');

    this.PHYSICS_TIMESTEP = 1 / 120;
    this.MAX_ACCUMULATOR = this.PHYSICS_TIMESTEP * 10;
    this.accumulator = 0;

    this.canvasWidth = 378;
    this.canvasHeight = 600;

    this.state = 'menu';
    this.gameState = null;
    this.currentLevel = null;
    this.currentBrickLayout = null;

    this.paddle = {
      x: 189,
      y: 560,
      width: 118,
      height: 16,
      baseWidth: 118,
      speed: 400,
      vx: 0
    };

    this.balls = [];
    this.drops = [];
    this.bricks = {};

    this.score = 0;
    this.lives = 3;
    this.combo = 1;
    this.nextExtraLife = 20000;

    this.powerUp = null;
    this.powerSeconds = 0;

    this.lastPaddleX = this.paddle.x;
    this.isPaused = false;
    this.assistPaddle = false;

    this.animationFrameId = null;
    this.lastFrameTime = 0;

    this.setupEventListeners();
  }

  setupEventListeners() {
    document.addEventListener('pointermove', (e) => this.handlePointerMove(e));
    document.addEventListener('touchmove', (e) => this.handleTouchMove(e));
    document.addEventListener('keydown', (e) => this.handleKeyDown(e));
    document.addEventListener('keyup', (e) => this.handleKeyUp(e));

    document.getElementById('assist-paddle').addEventListener('change', (e) => {
      this.assistPaddle = e.target.checked;
      if (this.assistPaddle === false) {
        this.assistPaddle = false;
      }
    });
  }

  handlePointerMove(e) {
    if (this.assistPaddle === false && e.pointerType !== 'touch') {
      this.updatePaddleFromPointer(e.clientX);
    }
  }

  handleTouchMove(e) {
    e.preventDefault();
    const touch = e.touches[0];
    this.updatePaddleFromPointer(touch.clientX);
    this.assistPaddle = false;
  }

  updatePaddleFromPointer(clientX) {
    const rect = this.canvas.getBoundingClientRect();
    const relativeX = clientX - rect.left;
    const canvasX = (relativeX / rect.width) * this.canvasWidth;

    this.paddle.x = Math.max(
      this.paddle.width / 2,
      Math.min(this.canvasWidth - this.paddle.width / 2, canvasX)
    );
    this.paddle.vx = (this.paddle.x - this.lastPaddleX) / (1/60);
    this.lastPaddleX = this.paddle.x;
  }

  handleKeyDown(e) {
    if (e.key === 'ArrowLeft' || e.key === 'a') {
      this.paddle.vx = -this.paddle.speed;
      this.assistPaddle = false;
    } else if (e.key === 'ArrowRight' || e.key === 'd') {
      this.paddle.vx = this.paddle.speed;
      this.assistPaddle = false;
    } else if (e.key === ' ') {
      e.preventDefault();
      this.handleLaunch();
    } else if (e.key === 'p' || e.key === 'P' || e.key === 'Escape') {
      e.preventDefault();
      this.togglePause();
    } else if (e.key === 'r' || e.key === 'R') {
      e.preventDefault();
      if (this.state === 'game-over') {
        this.handleRestart();
      }
    }
  }

  handleKeyUp(e) {
    if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'ArrowRight' || e.key === 'd') {
      this.paddle.vx = 0;
    }
  }

  handleLaunch() {
    if (this.state === 'ready' || (this.state === 'playing' && this.balls.some(b => b.stuck))) {
      const stuckBall = this.balls.find(b => b.stuck);
      if (stuckBall) {
        stuckBall.stuck = false;
        stuckBall.vx = (Math.random() - 0.5) * 200;
        stuckBall.vy = -300;
      }
    }
  }

  togglePause() {
    if (this.state === 'playing') {
      this.state = 'paused';
      this.isPaused = true;
    } else if (this.state === 'paused') {
      this.state = 'playing';
      this.isPaused = false;
      this.accumulator = 0;
    }
  }

  handleRestart() {
    if (this.state === 'game-over' && this.gameState) {
      window.ui.startNewRun(this.currentLevel.level_number || this.currentLevel.level);
    }
  }

  async loadLevel(levelNumber) {
    const gameState = await window.api.getGameState();

    const levels = gameState.user;
    const levelData = {
      level_number: levelNumber,
      base_speed: gameState.activeRun ? gameState.activeRun.level : levelNumber,
      speed_cap: 520 + (levelNumber - 1) * 25
    };

    this.currentLevel = levelData;
    this.currentBrickLayout = gameState.activeRun?.bricks || {};

    this.gameState = gameState.activeRun || {
      run_id: null,
      revision: 0,
      level: levelNumber,
      score: 0,
      lives: 3,
      combo: 1,
      next_extra_life: 20000,
      power_up: null,
      power_seconds: 0,
      paddle_width: 118,
      balls: [{ x: 189, y: 540, vx: 0, vy: 0, stuck: true, primary: true }],
      drops: [],
      bricks: this.currentBrickLayout,
      accumulated_time: 0
    };

    this.score = this.gameState.score;
    this.lives = this.gameState.lives;
    this.combo = this.gameState.combo;
    this.nextExtraLife = this.gameState.next_extra_life;
    this.powerUp = this.gameState.power_up;
    this.powerSeconds = this.gameState.power_seconds || 0;
    this.paddle.width = this.gameState.paddle_width;
    this.balls = this.gameState.balls.map(b => ({ ...b }));
    this.drops = this.gameState.drops.map(d => ({ ...d }));
    this.bricks = this.gameState.bricks ? JSON.parse(JSON.stringify(this.gameState.bricks)) : {};

    this.accumulator = this.gameState.accumulated_time || 0;

    if (!this.gameState.run_id) {
      const response = await window.api.startRun(levelNumber);
      this.gameState = response;
      this.gameState.balls = this.balls;
      this.gameState.drops = this.drops;
      this.gameState.bricks = this.bricks;
    }

    this.state = 'ready';
    this.startGameLoop();
  }

  startGameLoop() {
    const animate = (time) => {
      if (!this.lastFrameTime) {
        this.lastFrameTime = time;
      }

      const deltaTime = Math.min((time - this.lastFrameTime) / 1000, 0.033);
      this.lastFrameTime = time;

      if (!this.isPaused && this.state === 'playing') {
        this.accumulator += deltaTime;
        this.accumulator = Math.min(this.accumulator, this.MAX_ACCUMULATOR);

        while (this.accumulator >= this.PHYSICS_TIMESTEP) {
          this.update(this.PHYSICS_TIMESTEP);
          this.accumulator -= this.PHYSICS_TIMESTEP;
        }
      }

      this.render();
      this.animationFrameId = requestAnimationFrame(animate);
    };

    this.animationFrameId = requestAnimationFrame(animate);
  }

  update(dt) {
    if (this.state !== 'playing') return;

    this.updatePaddle(dt);
    this.updateBalls(dt);
    this.updateDrops(dt);
    this.updatePowerUp(dt);

    const allBroken = this.checkLevelComplete();
    if (allBroken) {
      this.completeLevel();
    }

    const noLives = this.checkGameOver();
    if (noLives) {
      this.endGame();
    }
  }

  updatePaddle(dt) {
    this.paddle.x += this.paddle.vx * dt;
    this.paddle.x = Math.max(
      this.paddle.width / 2,
      Math.min(this.canvasWidth - this.paddle.width / 2, this.paddle.x)
    );
    this.lastPaddleX = this.paddle.x;
  }

  updateBalls(dt) {
    for (const ball of this.balls) {
      if (ball.stuck) {
        ball.x = this.paddle.x;
        ball.y = this.paddle.y - 12;
        continue;
      }

      const startX = ball.x;
      const startY = ball.y;

      ball.x += ball.vx * dt;
      ball.y += ball.vy * dt;

      this.ensureMinimumSpeed(ball);
      this.capBallSpeed(ball);

      this.checkWallCollisions(ball, startX, startY, dt);
      this.checkPaddleCollision(ball, startX, startY);
      this.checkBrickCollisions(ball, startX, startY);
    }
  }

  ensureMinimumSpeed(ball) {
    const minSpeed = 100;
    const speed = Math.hypot(ball.vx, ball.vy);
    if (speed < minSpeed && speed > 0) {
      const scale = minSpeed / speed;
      ball.vx *= scale;
      ball.vy *= scale;
    }
  }

  capBallSpeed(ball) {
    const levelSpeed = this.currentLevel?.speed_cap || 520;
    const speed = Math.hypot(ball.vx, ball.vy);
    if (speed > levelSpeed) {
      const scale = levelSpeed / speed;
      ball.vx *= scale;
      ball.vy *= scale;
    }
  }

  checkWallCollisions(ball, startX, startY, dt) {
    const radius = 6;

    if (ball.x - radius < 0) {
      ball.x = radius;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + radius > this.canvasWidth) {
      ball.x = this.canvasWidth - radius;
      ball.vx = -Math.abs(ball.vx);
    }

    if (ball.y - radius < 0) {
      ball.y = radius;
      ball.vy = Math.abs(ball.vy);
    } else if (ball.y > this.canvasHeight) {
      this.loseBall(ball);
    }
  }

  checkPaddleCollision(ball, startX, startY) {
    const paddleTop = this.paddle.y - this.paddle.height / 2;
    const paddleBottom = this.paddle.y + this.paddle.height / 2;
    const paddleLeft = this.paddle.x - this.paddle.width / 2;
    const paddleRight = this.paddle.x + this.paddle.width / 2;
    const ballRadius = 6;

    if (
      ball.x + ballRadius >= paddleLeft &&
      ball.x - ballRadius <= paddleRight &&
      ball.y + ballRadius >= paddleTop &&
      ball.y - ballRadius <= paddleBottom &&
      startY < paddleTop
    ) {
      ball.y = paddleTop - ballRadius;

      const contactPos = (ball.x - paddleLeft) / this.paddle.width;
      const angle = (contactPos - 0.5) * Math.PI * 0.4;
      const speed = Math.hypot(ball.vx, ball.vy) || 300;

      ball.vx = Math.sin(angle) * speed * 0.8 + this.paddle.vx * 0.3;
      ball.vy = -Math.cos(angle) * speed;

      this.combo = 1;

      if (this.powerUp === 'sticky' && !ball.stuck) {
        ball.stuck = true;
        this.powerUp = null;
        this.powerSeconds = 0;
      }
    }
  }

  checkBrickCollisions(ball, startX, startY) {
    const ballRadius = 6;
    const gridSize = 30;

    for (const key in this.bricks) {
      const brick = this.bricks[key];
      if (brick.health <= 0) continue;

      const [row, col] = key.split(',').map(Number);
      const brickX = col * gridSize + gridSize / 2;
      const brickY = row * gridSize + gridSize / 2;
      const brickW = gridSize - 2;
      const brickH = gridSize - 2;

      if (this.sweptCollision(startX, startY, ball.x, ball.y, ballRadius, brickX, brickY, brickW, brickH)) {
        const damage = this.damageBrick(key, brick);
        if (damage > 0) {
          this.addScore(damage);

          const closestPoint = this.closestPointOnRect(ball.x, ball.y, brickX - brickW/2, brickY - brickH/2, brickW, brickH);
          const dx = ball.x - closestPoint.x;
          const dy = ball.y - closestPoint.y;
          const dist = Math.hypot(dx, dy);

          if (dist > 0) {
            ball.vx = (dx / dist) * Math.hypot(ball.vx, ball.vy) * 0.8;
            ball.vy = (dy / dist) * Math.hypot(ball.vx, ball.vy) * 0.8;
          }

          if (brick.drop && Math.random() < 0.3) {
            this.spawnDrop(brickX, brickY, brick.drop);
          }
        }
        break;
      }
    }
  }

  sweptCollision(x1, y1, x2, y2, r, bx, by, bw, bh) {
    const left = bx - bw / 2;
    const right = bx + bw / 2;
    const top = by - bh / 2;
    const bottom = by + bh / 2;

    const dx = x2 - x1;
    const dy = y2 - y1;
    const dist = Math.hypot(dx, dy);

    if (dist === 0) {
      return x2 > left && x2 < right && y2 > top && y2 < bottom;
    }

    const t = Math.max(0, Math.min(1, ((bx - x1) * dx + (by - y1) * dy) / (dist * dist)));
    const closestX = x1 + t * dx;
    const closestY = y1 + t * dy;

    const distToBrick = Math.hypot(bx - closestX, by - closestY);
    return distToBrick <= r;
  }

  closestPointOnRect(px, py, left, top, width, height) {
    return {
      x: Math.max(left, Math.min(px, left + width)),
      y: Math.max(top, Math.min(py, top + height))
    };
  }

  damageBrick(key, brick) {
    if (brick.type === 'solid') {
      return 0;
    }

    if (brick.health <= 0) {
      return 0;
    }

    brick.health--;

    if (brick.type === 'normal') {
      if (brick.health === 0) {
        return 100 * this.combo;
      }
    } else if (brick.type === 'strong') {
      if (brick.health === 1) {
        return 75 * this.combo;
      } else if (brick.health === 0) {
        return 250 * this.combo;
      }
    }

    return 0;
  }

  addScore(points) {
    const oldScore = this.score;
    this.score += points;

    const oldThreshold = Math.floor(oldScore / 20000);
    const newThreshold = Math.floor(this.score / 20000);

    if (newThreshold > oldThreshold) {
      this.lives++;
      this.nextExtraLife = (newThreshold + 1) * 20000;
    }

    this.combo = Math.min(5, this.combo + 1);
  }

  checkLevelComplete() {
    return Object.values(this.bricks).every(b => b.type === 'solid' || b.health <= 0);
  }

  completeLevel() {
    this.state = 'level-complete';
    const bonus = this.currentLevel.level_number * 1000;
    this.score += bonus;
    this.gameState.outcome = 'level-complete';
    this.gameState.next_level = this.currentLevel.level_number + 1;
  }

  checkGameOver() {
    return this.lives === 0;
  }

  endGame() {
    this.state = 'game-over';
  }

  loseBall(ball) {
    const idx = this.balls.indexOf(ball);
    if (idx !== -1) {
      this.balls.splice(idx, 1);
    }

    if (this.balls.length === 0) {
      this.lives--;
      if (this.lives <= 0) {
        this.endGame();
      } else {
        this.state = 'life-lost';
        this.powerUp = null;
        this.powerSeconds = 0;
        this.drops = [];
        setTimeout(() => {
          if (this.state === 'life-lost') {
            this.balls = [{
              x: this.paddle.x,
              y: this.paddle.y - 12,
              vx: 0,
              vy: 0,
              stuck: true,
              primary: true
            }];
            this.state = 'ready';
          }
        }, 1000);
      }
    }
  }

  updateDrops(dt) {
    for (let i = this.drops.length - 1; i >= 0; i--) {
      const drop = this.drops[i];
      drop.y += 200 * dt;

      const paddleTop = this.paddle.y - this.paddle.height / 2;
      const paddleBottom = this.paddle.y + this.paddle.height / 2;
      const paddleLeft = this.paddle.x - this.paddle.width / 2;
      const paddleRight = this.paddle.x + this.paddle.width / 2;

      if (
        drop.x >= paddleLeft &&
        drop.x <= paddleRight &&
        drop.y >= paddleTop &&
        drop.y <= paddleBottom
      ) {
        this.collectPowerUp(drop.type);
        this.drops.splice(i, 1);
      } else if (drop.y > this.canvasHeight) {
        this.drops.splice(i, 1);
      }
    }
  }

  spawnDrop(x, y, type) {
    this.drops.push({
      x,
      y,
      type,
      vx: 0,
      vy: 0
    });
  }

  collectPowerUp(type) {
    if (this.powerUp && this.powerUp !== type) {
      this.removePowerUp();
    }

    this.powerUp = type;
    this.powerSeconds = 20;

    if (type === 'wide') {
      this.paddle.width = this.paddle.baseWidth * 1.5;
    } else if (type === 'slow') {
      for (const ball of this.balls) {
        ball.vx *= 0.7;
        ball.vy *= 0.7;
      }
    } else if (type === 'multiball') {
      if (this.balls.length === 1) {
        const primaryBall = this.balls[0];
        this.balls.push({
          x: primaryBall.x - 20,
          y: primaryBall.y,
          vx: primaryBall.vx - 100,
          vy: primaryBall.vy,
          stuck: false,
          primary: false
        });
      }
    } else if (type === 'sticky') {
      // No immediate action
    }
  }

  removePowerUp() {
    if (this.powerUp === 'wide') {
      this.paddle.width = this.paddle.baseWidth;
    } else if (this.powerUp === 'slow') {
      for (const ball of this.balls) {
        const speed = Math.hypot(ball.vx, ball.vy);
        const newSpeed = Math.min(speed / 0.7, this.currentLevel?.speed_cap || 520);
        if (speed > 0) {
          ball.vx = (ball.vx / speed) * newSpeed;
          ball.vy = (ball.vy / speed) * newSpeed;
        }
      }
    } else if (this.powerUp === 'multiball') {
      this.balls = this.balls.filter(b => b.primary !== false || !b.secondary_only);
    }
  }

  updatePowerUp(dt) {
    if (this.powerUp && this.powerSeconds > 0) {
      this.powerSeconds -= dt;
      if (this.powerSeconds <= 0) {
        this.removePowerUp();
        this.powerUp = null;
        this.powerSeconds = 0;
      }
    }
  }

  render() {
    this.ctx.fillStyle = '#0f0f1e';
    this.ctx.fillRect(0, 0, this.canvasWidth, this.canvasHeight);

    this.renderBricks();
    this.renderDrops();
    this.renderPaddle();
    this.renderBalls();
    this.renderUI();
  }

  renderBricks() {
    const gridSize = 30;
    const colors = {
      normal: '#56c7ff',
      strong: '#ffd166',
      solid: '#6b6b7e'
    };

    for (const key in this.bricks) {
      const brick = this.bricks[key];
      const [row, col] = key.split(',').map(Number);
      const x = col * gridSize + 1;
      const y = row * gridSize + 1;

      if (brick.health <= 0 && brick.type !== 'solid') continue;

      this.ctx.fillStyle = colors[brick.type] || '#56c7ff';
      this.ctx.fillRect(x, y, gridSize - 2, gridSize - 2);

      if (brick.type === 'strong' && brick.health > 0) {
        this.ctx.strokeStyle = brick.health === 1 ? '#ff6b6b' : '#ffd166';
        this.ctx.lineWidth = 2;
        this.ctx.strokeRect(x, y, gridSize - 2, gridSize - 2);
      }
    }
  }

  renderDrops() {
    for (const drop of this.drops) {
      const colors = {
        wide: '#56c7ff',
        slow: '#7ee787',
        multiball: '#ffd166',
        sticky: '#ff6b6b'
      };

      this.ctx.fillStyle = colors[drop.type] || '#56c7ff';
      this.ctx.beginPath();
      this.ctx.arc(drop.x, drop.y, 6, 0, Math.PI * 2);
      this.ctx.fill();
    }
  }

  renderPaddle() {
    this.ctx.fillStyle = '#7ee787';
    this.ctx.fillRect(
      this.paddle.x - this.paddle.width / 2,
      this.paddle.y - this.paddle.height / 2,
      this.paddle.width,
      this.paddle.height
    );
  }

  renderBalls() {
    for (const ball of this.balls) {
      this.ctx.fillStyle = ball.primary ? '#56c7ff' : '#ffd166';
      this.ctx.beginPath();
      this.ctx.arc(ball.x, ball.y, 6, 0, Math.PI * 2);
      this.ctx.fill();
    }
  }

  renderUI() {
    if (this.state === 'ready') {
      this.ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
      this.ctx.fillRect(0, 0, this.canvasWidth, this.canvasHeight);

      this.ctx.fillStyle = '#56c7ff';
      this.ctx.font = 'bold 24px sans-serif';
      this.ctx.textAlign = 'center';
      this.ctx.fillText('Press Space to Launch', this.canvasWidth / 2, this.canvasHeight / 2);
    } else if (this.state === 'paused') {
      this.ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
      this.ctx.fillRect(0, 0, this.canvasWidth, this.canvasHeight);

      this.ctx.fillStyle = '#ffd166';
      this.ctx.font = 'bold 24px sans-serif';
      this.ctx.textAlign = 'center';
      this.ctx.fillText('PAUSED', this.canvasWidth / 2, this.canvasHeight / 2);
    } else if (this.state === 'life-lost') {
      this.ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
      this.ctx.fillRect(0, 0, this.canvasWidth, this.canvasHeight);

      this.ctx.fillStyle = '#ff6b6b';
      this.ctx.font = 'bold 24px sans-serif';
      this.ctx.textAlign = 'center';
      this.ctx.fillText('LIFE LOST', this.canvasWidth / 2, this.canvasHeight / 2);
    }
  }

  async saveState() {
    if (!this.gameState || !this.gameState.run_id) return;

    try {
      const stateToSave = {
        level: this.currentLevel.level_number,
        score: this.score,
        lives: this.lives,
        combo: this.combo,
        next_extra_life: this.nextExtraLife,
        power_up: this.powerUp,
        power_seconds: this.powerSeconds,
        paddle_width: this.paddle.width,
        balls: this.balls,
        drops: this.drops,
        bricks: this.bricks,
        accumulated_time: this.accumulator
      };

      await window.api.saveRun(
        this.gameState.run_id,
        this.gameState.revision,
        stateToSave
      );

      this.gameState.revision++;
    } catch (err) {
      console.error('Error saving state:', err);
    }
  }

  destroy() {
    if (this.animationFrameId) {
      cancelAnimationFrame(this.animationFrameId);
    }
  }
}

window.game = new BrickfallGame();

class UIManager {
  constructor() {
    this.currentUser = null;
    this.gameState = null;
    this.lastSaveTime = 0;
    this.saveInterval = 5000;
    this.setupEventListeners();
  }

  setupEventListeners() {
    document.getElementById('sign-in-form').addEventListener('submit', (e) => this.handleSignIn(e));
    document.getElementById('sign-out-btn').addEventListener('click', () => this.handleSignOut());

    document.getElementById('launch-btn').addEventListener('click', () => window.game.handleLaunch());
    document.getElementById('pause-btn').addEventListener('click', () => this.togglePause());
    document.getElementById('continue-btn').addEventListener('click', () => this.togglePause());
    document.getElementById('restart-btn').addEventListener('click', () => window.game.handleRestart());

    const tabBtns = document.querySelectorAll('.tab-btn');
    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => this.switchTab(btn.dataset.tab));
    });

    window.addEventListener('focus', () => this.handleWindowFocus());
  }

  async handleSignIn(e) {
    e.preventDefault();

    const email = document.getElementById('email').value;
    const password = document.getElementById('password').value;
    const messageEl = document.getElementById('sign-in-message');

    try {
      messageEl.textContent = 'Signing in...';
      const result = await window.api.signIn(email, password);

      window.api.setToken(result.token);
      this.currentUser = result.user;

      this.showGameScreen();
      await this.loadGameState();
    } catch (err) {
      messageEl.textContent = err.data?.error || 'Sign in failed';
      messageEl.className = 'message error';
    }
  }

  async handleSignOut() {
    try {
      await window.api.signOut();
      window.api.clearToken();
      this.currentUser = null;
      window.game.destroy();
      this.showSignInScreen();
    } catch (err) {
      console.error('Sign out error:', err);
    }
  }

  showSignInScreen() {
    document.getElementById('sign-in-screen').classList.add('active');
    document.getElementById('game-screen').classList.remove('active');
  }

  showGameScreen() {
    document.getElementById('sign-in-screen').classList.remove('active');
    document.getElementById('game-screen').classList.add('active');

    const playerName = this.currentUser.name || this.currentUser.email;
    document.getElementById('player-name').textContent = `${playerName} (${this.currentUser.initials})`;
  }

  async loadGameState() {
    try {
      this.gameState = await window.api.getGameState();

      document.getElementById('best-score').textContent = this.gameState.user.best_score;

      this.renderLevelButtons();
      this.renderLeaderboard(this.gameState.leaderboard);
      this.renderRunHistory(this.gameState.runHistory);

      if (this.gameState.activeRun) {
        this.showContinueOption();
        window.game.loadLevel(this.gameState.activeRun.level);
      }

      this.startAutoSave();
    } catch (err) {
      console.error('Error loading game state:', err);
    }
  }

  renderLevelButtons() {
    const container = document.getElementById('level-buttons');
    container.innerHTML = '';

    for (let i = 1; i <= 10; i++) {
      const btn = document.createElement('button');
      btn.className = 'level-btn';
      btn.textContent = i;

      if (i <= this.gameState.unlockedLevels) {
        btn.className += ' unlocked';
        btn.addEventListener('click', () => this.startNewRun(i));
      } else {
        btn.disabled = true;
      }

      if (this.gameState.activeRun && this.gameState.activeRun.level === i) {
        btn.className += ' active';
      }

      container.appendChild(btn);
    }
  }

  renderLeaderboard(entries) {
    const container = document.getElementById('leaderboard');
    container.innerHTML = '';

    entries.forEach((entry, idx) => {
      const div = document.createElement('div');
      div.className = 'leaderboard-entry';

      div.innerHTML = `
        <span class="leaderboard-rank">#${idx + 1}</span>
        <span class="leaderboard-name">${entry.initials}</span>
        <span class="leaderboard-score">${entry.score}</span>
      `;

      container.appendChild(div);
    });
  }

  renderRunHistory(history) {
    const container = document.getElementById('run-history');
    container.innerHTML = '';

    if (!history || history.length === 0) {
      container.innerHTML = '<p style="color: var(--text-secondary);">No run history yet</p>';
      return;
    }

    history.forEach(record => {
      const div = document.createElement('div');
      div.className = 'history-entry';

      const outcomeClass = record.outcome === 'completed' ? 'completed' : 'game-over';
      const dateStr = new Date(record.finished_at).toLocaleDateString();

      div.innerHTML = `
        <div class="history-entry-header">
          <span>Level ${record.level}</span>
          <span class="history-outcome ${outcomeClass}">${record.outcome}</span>
        </div>
        <div class="history-details">
          <div class="history-detail-item">
            <span class="history-detail-label">Score:</span>
            <span class="history-detail-value">${record.score}</span>
          </div>
          <div class="history-detail-item">
            <span class="history-detail-label">Date:</span>
            <span class="history-detail-value">${dateStr}</span>
          </div>
        </div>
      `;

      container.appendChild(div);
    });
  }

  async startNewRun(levelNumber) {
    try {
      window.game.destroy();
      window.game = new BrickfallGame();
      await window.game.loadLevel(levelNumber);
      window.game.state = 'ready';
      this.updateUI();
    } catch (err) {
      this.showEventMessage(`Error starting level: ${err.message}`, 'error');
    }
  }

  showContinueOption() {
    if (this.gameState.activeRun) {
      document.getElementById('launch-btn').style.display = 'inline-block';
      document.getElementById('pause-btn').style.display = 'inline-block';
    }
  }

  togglePause() {
    if (window.game.state === 'playing') {
      window.game.togglePause();
      document.getElementById('pause-btn').style.display = 'none';
      document.getElementById('continue-btn').style.display = 'inline-block';
      this.showEventMessage('Game paused');
    } else if (window.game.state === 'paused') {
      window.game.togglePause();
      document.getElementById('pause-btn').style.display = 'inline-block';
      document.getElementById('continue-btn').style.display = 'none';
      this.showEventMessage('Game resumed');
    }
  }

  switchTab(tabName) {
    document.querySelectorAll('.tab-pane').forEach(pane => {
      pane.classList.remove('active');
    });
    document.getElementById(tabName).classList.add('active');

    document.querySelectorAll('.tab-btn').forEach(btn => {
      btn.classList.remove('active');
    });
    document.querySelector(`[data-tab="${tabName}"]`).classList.add('active');
  }

  updateUI() {
    const game = window.game;

    document.getElementById('hud-score').textContent = game.score;
    document.getElementById('hud-lives').textContent = game.lives;
    document.getElementById('hud-level').textContent = game.currentLevel?.level_number || 1;
    document.getElementById('hud-combo').textContent = `x${game.combo}`;

    if (game.powerUp) {
      document.getElementById('power-up-display').style.display = 'block';
      document.getElementById('power-up-name').textContent = game.powerUp.toUpperCase();

      const percentage = Math.max(0, (game.powerSeconds / 20) * 100);
      document.getElementById('power-timer-bar').style.width = `${percentage}%`;
    } else {
      document.getElementById('power-up-display').style.display = 'none';
    }

    document.getElementById('revision-display').textContent = game.gameState?.revision || 0;

    if (game.state === 'ready') {
      document.getElementById('launch-btn').style.display = 'inline-block';
      document.getElementById('pause-btn').style.display = 'none';
      document.getElementById('restart-btn').style.display = 'none';
      document.getElementById('continue-btn').style.display = 'none';
      this.canvas.focus();
    } else if (game.state === 'playing') {
      document.getElementById('launch-btn').style.display = 'none';
      document.getElementById('pause-btn').style.display = 'inline-block';
      document.getElementById('restart-btn').style.display = 'none';
      document.getElementById('continue-btn').style.display = 'none';
    } else if (game.state === 'paused') {
      document.getElementById('pause-btn').style.display = 'none';
      document.getElementById('continue-btn').style.display = 'inline-block';
    } else if (game.state === 'game-over') {
      document.getElementById('pause-btn').style.display = 'none';
      document.getElementById('continue-btn').style.display = 'none';
      document.getElementById('restart-btn').style.display = 'inline-block';
      this.showEventMessage('Game Over');
    } else if (game.state === 'level-complete') {
      document.getElementById('pause-btn').style.display = 'none';
      document.getElementById('launch-btn').style.display = 'inline-block';
      this.showEventMessage('Level Complete!');
    }

    requestAnimationFrame(() => this.updateUI());
  }

  showEventMessage(message, type = 'info') {
    const el = document.getElementById('event-message');
    el.textContent = message;
    el.className = 'event-message active';

    setTimeout(() => {
      el.classList.remove('active');
    }, 3000);
  }

  startAutoSave() {
    setInterval(() => {
      if (window.game && window.game.state === 'playing' && window.game.gameState) {
        window.game.saveState();
      }
    }, this.saveInterval);
  }

  handleWindowFocus() {
    if (this.gameState && !window.game.gameState) {
      this.loadGameState();
    }
  }
}

window.ui = new UIManager();

document.addEventListener('DOMContentLoaded', async () => {
  const token = localStorage.getItem('auth_token');
  if (token) {
    window.api.setToken(token);
    try {
      const response = await window.api.getGameState();
      window.ui.currentUser = response.user;
      window.ui.showGameScreen();
      window.ui.loadGameState();
    } catch (err) {
      window.ui.showSignInScreen();
    }
  } else {
    window.ui.showSignInScreen();
  }

  window.ui.updateUI();
});

